    private async Task RegisterFuelPaymentV13Async(TelemetrySnapshot data,float liters,decimal price,string station,string city){var token=SecureTokenStore.Read();if(string.IsNullOrWhiteSpace(token)){StatusText.Text="TransPoli • sessão não encontrada";return;}var amount=Math.Round((decimal)liters*price,2);try{var payload=new{liters,pricePerLiter=price,amount,station,city,odometerKm=data.OdometerKm,truckBrand=data.TruckBrand,truckModel=data.TruckModel,licensePlate=data.LicensePlate,tripId=_serverTripId};using var request=new HttpRequestMessage(HttpMethod.Post,$"{ApiBaseUrl}/me/expenses/fuel-payment");request.Headers.TryAddWithoutValidation("Authorization",$"Bearer {token}");request.Headers.TryAddWithoutValidation("Cookie",$"truckhub_session={token}");request.Content=new StringContent(JsonSerializer.Serialize(payload),Encoding.UTF8,"application/json");using var response=await _http.SendAsync(request);var text=await response.Content.ReadAsStringAsync();if(!response.IsSuccessStatusCode){StatusText.Text="TransPoli • "+TryApiError(text,"não foi possível lançar o abastecimento");return;}_refuelings.Add(new RefuelingRecord{Id=Guid.NewGuid().ToString("N"),RecordedAtUtc=DateTime.UtcNow,Station=station,Location=city,Liters=liters,FuelBefore=_fuelBefore,FuelAfter=_fuelAfter,OdometerKm=data.OdometerKm,Truck=$"{data.TruckBrand} {data.TruckModel}".Trim(),LicensePlate=data.LicensePlate??""});SaveOperations();UpdateOpsCounters();_pendingRefuelTelemetry=null;_pendingRefuelLiters=0;StatusText.Text=$"TransPoli • abastecimento confirmado • R$ {amount:0.00} debitado do banco";CloseOperationalModal();}catch{StatusText.Text="TransPoli • erro de comunicação ao registrar o abastecimento";}}
