public sealed class Ets2TruckInfo{public string ProfileName{get;init;}="";public string Brand{get;init;}="";public string Model{get;init;}="";public string Plate{get;init;}="";public float OdometerKm{get;init;}public float FuelLiters{get;init;}public string DisplayName=>string.IsNullOrWhiteSpace(Brand)&&string.IsNullOrWhiteSpace(Model)?"Caminhão":$"{Brand} {Model}".Trim();}
public sealed class Ets2SaveScanResult{public List<Ets2TruckInfo> Trucks{get;}=new();public bool ProtectedSaveFound{get;init;}public string Description{get;init;}="";}
public static class Ets2SaveScanner{public static Ets2SaveScanResult Scan(){var result=new Ets2SaveScanResult{Description="Leitura dos perfis/saves locais (somente leitura)."};try{var roots=new[]{Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"Euro Truck Simulator 2"),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"American Truck Simulator")};foreach(var root in roots.Distinct(StringComparer.OrdinalIgnoreCase)){if(!Directory.Exists(root))continue;foreach(var folderName in new[]{"profiles","steam_profiles"}){var folder=Path.Combine(root,folderName);if(!Directory.Exists(folder))continue;foreach(var profile in Directory.EnumerateDirectories(folder)){var profileName=Path.GetFileName(profile);foreach(var save in Directory.EnumerateDirectories(profile)){var game=Path.Combine(save,"game.sii");if(!File.Exists(game))continue;try{var text=File.ReadAllText(game,Encoding.UTF8);foreach(Match m in Regex.Matches(text,"(?s)truck:\\s*\\S+\\s*\\{(?<body>.*?)\\}")){var body=m.Groups["body"].Value;var brand=ReadSii(body,"brand");var model=ReadSii(body,"truck_name");if(string.IsNullOrWhiteSpace(model))model=ReadSii(body,"model");var plate=ReadSii(body,"license_plate");var odo=ReadFloat(body,"odometer");var fuel=ReadFloat(body,"fuel_relative");result.Trucks.Add(new Ets2TruckInfo{ProfileName=profileName,Brand=brand,Model=model,Plate=plate,OdometerKm=odo,FuelLiters=fuel});}}catch{result.ProtectedSaveFound=true;}}}}}}}catch{ }return result;}
    private static string ReadSii(string body,string key){var pattern="\\b"+Regex.Escape(key)+"\\s*:\\s*(?:\\\"(?<q>[^\\\"]*)\\\"|(?<v>[^\\s}]+))";var m=Regex.Match(body,pattern,RegexOptions.IgnoreCase);return m.Success?(m.Groups["q"].Success?m.Groups["q"].Value:m.Groups["v"].Value):string.Empty;}
    private static float ReadFloat(string body,string key){var value=ReadSii(body,key);return float.TryParse(value,NumberStyles.Float,CultureInfo.InvariantCulture,out var n)?n:0;}
}
public static class V13ModuleBootstrap{private static bool _registered;internal static void Register(MainWindow window){if(_registered)return;_registered=true;window.AddHandler(Button.ClickEvent,new RoutedEventHandler((s,e)=>{if(e.OriginalSource is not Button b)return;var tag=b.Tag?.ToString()?.Trim().ToLowerInvariant()??string.Empty;var text=b.Content?.ToString()?.Trim().ToUpperInvariant()??string.Empty;if(tag=="feature-garage"||text.Contains("GARAGEM")){e.Handled=true;window.ShowGarageFromSaveV13();}else if(text.Contains("ABASTECIMENTO")||text.Contains("COMBUSTÍVEL")){e.Handled=true;window.ShowFuelPaymentModalV13();}}),true);}}
